}

{
 "command": "make test-fast 2>&1 | tail -15",
 "description": "Run the fast unit test suite"
}

{
 "command": "python -m pytest tests/test_refunds.py -v 2>&1 | tail -4; git stash -u -q && python -m pytest -m \"not postgres and not integration\" -q 2>&1 | tail -2; git stash pop -q",
 "description": "Run new test; check currency errors pre-exist"
}

{
 "command": "python -m pytest -W error tests/test_refunds.py -q 2>&1 | tail -3",
 "description": "Run new test with warnings as errors"
}

